// Shim for the VFX Armory's abilities/cinematic/lib/models.js, generated by scripts/engine/armory/vendor.mts from the Armory @ 734f147f3; do not edit.
// Partial: the cinematic pack's model table names all nine of its models; the game carries only those of the effects it vendors (no shark or wolf: no traceable source), each loaded before its effect is built.
/**
 * Model loading for the cinematic pack (ported from achrefelouafi/AbilityCastingThreeJS, MIT).
 *
 * The source App loaded every model at boot and handed the rigs to the
 * abilities as `ctx.models`. Here a model is loaded the first time its ability
 * is warmed (see `../index.js`), built into its rig exactly as the source App
 * built it, and parked in `cinModels`, which the ability constructors read.
 */
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { settings } from './settings.js';
import { modelUrl } from '../../../remake.js';
import { buildDragonRig } from './assets/DragonRig.js';
import { buildGyroscopeRig } from './assets/GyroscopeRig.js';
import { buildAmethystRig } from './assets/AmethystRig.js';
import { buildTomeRig } from './assets/TomeRig.js';
import { buildReliquaryRig } from './assets/ReliquaryRig.js';

const ROOT = '/assets/armory/cinematic/models/';

/** model key -> { url, build(gltf|null), optional } — `optional` rigs have a stand-in. */
const MODELS = {
  dragon: { url: 'dragon.glb', build: (g) => buildDragonRig(g, { wingspan: settings.dragon.wingspan }) },
  gyro: { url: 'magical_gyroscope.glb', build: (g) => buildGyroscopeRig(g, { height: settings.gyro.size }) },
  amethyst: { url: 'amethyst_stones.glb', optional: true, build: (g) => buildAmethystRig(g) },
  tome: { url: 'arcane_tome.glb', optional: true, build: (g) => buildTomeRig(g) },
  reliquary: { url: 'wildroot_reliquary.glb', optional: true, build: (g) => buildReliquaryRig(g) }
};

/** Built rigs, by source key (`cinModels.shark`). */
export const cinModels = {};

const pending = new Map();
let loader = null;

/**
 * Load and build one rig. Idempotent; resolves once `cinModels[key]` is set.
 * @param {string|null} key a key of MODELS, or null for abilities with no model
 */
export function loadCinModel(key) {
  if (!key || key in cinModels) return Promise.resolve(cinModels[key]);
  if (pending.has(key)) return pending.get(key);
  const spec = MODELS[key];
  loader ??= new GLTFLoader();
  const job = loader
    .loadAsync(modelUrl(ROOT + spec.url))
    .catch((error) => {
      if (!spec.optional) console.warn(`cinematic: ${spec.url} failed to load`, error);
      return null;
    })
    .then((gltf) => {
      cinModels[key] = gltf || spec.optional ? spec.build(gltf) : null;
      return cinModels[key];
    })
    .finally(() => pending.delete(key));
  pending.set(key, job);
  return job;
}
